class ArchitecturalScore {
    constructor(payload) {
        this.payload = payload;
        this.scores = { seo: 10, performance: 10, mobile: 10, complexidade: 0 };
        this.feedback = [];
    }

    calculate() {
        this._evalPerformance();
        this._evalSEO();
        this._evalMobile();
        this._evalComplexity();
        return {
            scores: this._normalizeScores(),
            recommendation: this._generateAutoRecommendation(),
            feedback: this.feedback
        };
    }

    _evalPerformance() {
        const { heroSection, menuType, adSlots, commentSystem, postModules } = this.payload;
        if (heroSection === 'carousel') { this.scores.performance -= 2; this.feedback.push('-2 Perf: O Carrossel atrasa o LCP.'); }
        if (menuType === 'mega-menu') { this.scores.performance -= 1; this.feedback.push('-1 Perf: Mega-Menu duplica as tags <li> ocultas.'); }
        if (adSlots) { this.scores.performance -= 3; this.feedback.push('-3 Perf: Scripts externos de AdSense bloqueiam a thread principal.'); }
        if (commentSystem !== 'blogger-native') { this.scores.performance -= 2; this.feedback.push('-2 Perf: Comentários externos geram iframes pesados.'); }
        if (postModules && postModules.includes('related-posts')) { this.scores.performance -= 1; this.feedback.push('-1 Perf: Artigos relacionados requerem requisições à API após carregamento.'); }
    }

    _evalSEO() {
        const { paginationStyle, coreFeatures, gridLayout, adSlots } = this.payload;
        if (!coreFeatures || !coreFeatures.includes('seo-premium')) { this.scores.seo -= 4; this.feedback.push('-4 SEO: Sem Schema.org, o Google não indexa corretamente.'); }
        if (paginationStyle === 'infinite-scroll') { this.scores.seo -= 2; this.feedback.push('-2 SEO: Os crawlers do Google odeiam Infinite Scroll.'); }
        if (gridLayout === 'mural' || gridLayout === 'quadrado') { this.scores.seo -= 1; }
        if (adSlots) { this.scores.seo -= 1; }
    }

    _evalMobile() {
        const { menuType, sidebarPosition, heroSection } = this.payload;
        if (menuType === 'simple' && sidebarPosition === 'right') { this.scores.mobile -= 2; this.feedback.push('-2 Mobile: Sem Offcanvas, os menus horizontais esmagam num ecrã pequeno.'); }
        if (heroSection === 'grid-mosaic') { this.scores.mobile -= 1; this.feedback.push('-1 Mobile: Grelhas em mosaico perdem a hierarquia no telemóvel.'); }
    }

    _evalComplexity() {
        const { heroSection, menuType, gridLayout } = this.payload;
        if (menuType === 'mega-menu') this.scores.complexidade += 3;
        if (heroSection === 'carousel') this.scores.complexidade += 2;
        if (gridLayout === 'mural') this.scores.complexidade += 1;
        if (this.scores.complexidade >= 6) { this.feedback.push('[AVISO] Este template exige gestão avançada de Marcadores (Labels) no painel do Blogger.'); }
    }

    _normalizeScores() {
        return {
            seo: Math.max(0, Math.min(10, this.scores.seo)),
            performance: Math.max(0, Math.min(10, this.scores.performance)),
            mobile: Math.max(0, Math.min(10, this.scores.mobile)),
            complexidade: Math.max(0, Math.min(10, this.scores.complexidade))
        };
    }

    _generateAutoRecommendation() {
        const s = this._normalizeScores();
        if (s.performance < 6) return 'Recomendação Crítica de Performance: Desative os Anúncios ou substitua o Carrossel pelo Destaque Estático.';
        if (s.seo < 8) return 'Alerta SEO: Troque a Paginação Infinita por Botões Clássicos.';
        if (s.mobile < 8) return 'Ajuste Mobile: O seu menu está demasiado denso. Ative a Navegação Offcanvas.';
        return 'Arquitetura Excelente. Este template está otimizado para os mais altos padrões do Core Web Vitals.';
    }
}

module.exports = ArchitecturalScore;
